from concurrent.futures import ThreadPoolExecutor  # noqa: F401  (used by the implementation in phase 2)


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, in input order.

    Each element is computed with parity() on a thread pool. The result
    list is positionally aligned with xs, and its contents and order do
    not depend on how many workers the pool uses.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([0]) == [0]


def test_parities_mixed_signs() -> None:
    assert parities([-3, -2, -1, 0, 1, 2, 3]) == [1, 0, 1, 0, 1, 0, 1]


def test_parities_preserves_input_order() -> None:
    xs = list(range(1000))
    expected = [x % 2 for x in xs]
    assert parities(xs) == expected


def test_parities_matches_sequential_parity() -> None:
    xs = [5, 8, 13, 21, 34, 55, 89, 144]
    assert parities(xs) == [parity(x) for x in xs]
